bool UartCommandWindow::show(CWnd* owner,const std::wstring& ini,Send send,Start start,std::function<void(size_t)> stop,std::function<uint64_t(size_t)> generation){if(!GetSafeHwnd()){ini_=ini;send_=std::move(send);start_=std::move(start);stop_=std::move(stop);generation_=std::move(generation);if(!Create(IDD_UART_COMMANDS,owner))return false;}ShowWindow(SW_SHOW);SetForegroundWindow();return true;}
BOOL UartCommandWindow::OnInitDialog(){CDialog::OnInitDialog();SetWindowTextW(L"UART Commands / Step scripts");font_=make_ui_font(m_hWnd,std::wstring(AfxGetApp()->m_lpCmdLine).find(L"--font125")!=std::wstring::npos);
    const auto child=[&](const wchar_t* cls,const wchar_t* title,DWORD style,int id){return ::CreateWindowW(cls,title,WS_CHILD|WS_VISIBLE|style,0,0,1,1,m_hWnd,reinterpret_cast<HMENU>(static_cast<INT_PTR>(id)),nullptr,nullptr);};
    mode_=child(L"COMBOBOX",L"",CBS_DROPDOWNLIST|WS_TABSTOP,Mode);for(auto s:{L"Commands",L"Step scripts"})::SendMessageW(mode_,CB_ADDSTRING,0,reinterpret_cast<LPARAM>(s));::SendMessageW(mode_,CB_SETCURSEL,0,0);
    port_=child(L"COMBOBOX",L"",CBS_DROPDOWNLIST|WS_TABSTOP,Port);for(auto s:{L"Port A",L"Port B"})::SendMessageW(port_,CB_ADDSTRING,0,reinterpret_cast<LPARAM>(s));::SendMessageW(port_,CB_SETCURSEL,0,0);
    group_=child(L"COMBOBOX",L"",CBS_DROPDOWNLIST|WS_TABSTOP|WS_VSCROLL,Group);
    list_=child(L"LISTBOX",L"",WS_BORDER|WS_VSCROLL|WS_TABSTOP|LBS_NOTIFY|LBS_NOINTEGRALHEIGHT,List);
    value_=child(L"EDIT",L"0",WS_BORDER|WS_TABSTOP|ES_AUTOHSCROLL,Value);::SendMessageW(value_,EM_SETLIMITTEXT,64,0);
    slider_=child(TRACKBAR_CLASSW,L"",WS_TABSTOP|TBS_HORZ|TBS_NOTICKS,Slider);::SendMessageW(slider_,TBM_SETRANGE,TRUE,MAKELONG(0,1000));
    hint_=child(L"STATIC",L"Select a named command; only Send / Start transmits. Expect matches raw RX, not a protocol ACK. Private definitions load without auto-start.",SS_NOPREFIX,0);
    for(const auto& item:std::vector<std::pair<int,const wchar_t*>>{{Minus,L"-"},{Plus,L"+"},{New,L"New..."},{Edit,L"Edit..."},{Remove,L"Remove"},{Up,L"Up"},{Down,L"Down"},{Import,L"Import..."},{Export,L"Export..."},{SendNow,L"Send / Start"},{Stop,L"Stop"},{SaveResults,L"Save results..."}})buttons_.push_back(child(L"BUTTON",item.second,WS_TABSTOP|BS_PUSHBUTTON,item.first));
    status_=child(L"EDIT",L"No command is sent automatically.",WS_BORDER|WS_VSCROLL|ES_READONLY|ES_MULTILINE,0);
    ::EnumChildWindows(m_hWnd,[](HWND h,LPARAM f)->BOOL{::SendMessageW(h,WM_SETFONT,static_cast<WPARAM>(f),FALSE);return TRUE;},reinterpret_cast<LPARAM>(font_));ready_=true;SetWindowPos(nullptr,80,60,980,740,SWP_NOZORDER);rebuild();layout();default_second_=true;file(true,true);return TRUE;}
bool UartCommandWindow::steps_mode()const{return pick(mode_)==1;}size_t UartCommandWindow::port()const{return pick(port_)==1?1:0;}
int UartCommandWindow::selected()const{const auto n=::SendMessageW(list_,LB_GETCURSEL,0,0);return n>=0&&static_cast<size_t>(n)<indexes_.size()?static_cast<int>(indexes_[n]):-1;}
void UartCommandWindow::rebuild(int select){if(!ready_)return;const auto filter=text(group_);std::set<std::wstring> groups;for(const auto& c:commands_)groups.insert(uart_wide(c.group));::SendMessageW(group_,CB_RESETCONTENT,0,0);::SendMessageW(group_,CB_ADDSTRING,0,reinterpret_cast<LPARAM>(L"(all groups)"));for(const auto& g:groups)::SendMessageW(group_,CB_ADDSTRING,0,reinterpret_cast<LPARAM>(g.c_str()));const auto index=::SendMessageW(group_,CB_FINDSTRINGEXACT,static_cast<WPARAM>(-1),reinterpret_cast<LPARAM>(filter.c_str()));::SendMessageW(group_,CB_SETCURSEL,index>=0?index:0,0);::EnableWindow(group_,!steps_mode());
    ::SendMessageW(list_,LB_RESETCONTENT,0,0);indexes_.clear();const auto chosen=text(group_);const auto count=steps_mode()?steps_.size():commands_.size();for(size_t i=0;i<count;++i){const auto& c=steps_mode()?steps_[i].command:commands_[i];if(!steps_mode()&&pick(group_)>0&&uart_wide(c.group)!=chosen)continue;const auto label=(steps_mode()?std::to_wstring(i+1)+L". ":L"")+uart_wide(c.group)+L" / "+uart_wide(c.name);const auto at=::SendMessageW(list_,LB_ADDSTRING,0,reinterpret_cast<LPARAM>(label.c_str()));indexes_.push_back(i);if(static_cast<int>(i)==select)::SendMessageW(list_,LB_SETCURSEL,at,0);}
    if(selected()<0&&!indexes_.empty())::SendMessageW(list_,LB_SETCURSEL,0,0);selection();}
void UartCommandWindow::selection(){const auto n=selected();const bool valid=n>=0;::EnableWindow(value_,valid&&!steps_mode());::EnableWindow(slider_,valid&&!steps_mode());for(const auto id:{Minus,Plus})::EnableWindow(::GetDlgItem(m_hWnd,id),valid&&!steps_mode());if(valid){const auto& c=steps_mode()?steps_[n].command:commands_[n];::SetWindowTextW(value_,number(c.value).c_str());const auto position=c.maximum==c.minimum?0:static_cast<int>((c.value-c.minimum)/(c.maximum-c.minimum)*1000);::SendMessageW(slider_,TBM_SETPOS,TRUE,position);}}
void UartCommandWindow::edit(bool create){if(files_.busy()||closing_){notice(L"Wait for file work.");return;}const auto n=selected();if(!create&&n<0)return;const bool script=steps_mode();PanelCommand c=create?PanelCommand{}:script?steps_[n].command:commands_[n];if(create){c.group="User";c.name="Command "+std::to_string((script?steps_.size():commands_.size())+1);c.body="";}
    const std::vector<std::wstring> endings={L"None",L"CR",L"LF",L"CRLF"},checksums={L"None",L"Sum8",L"XOR8",L"CRC16 Modbus",L"CRC16 CCITT-FALSE",L"CRC32"};
    std::vector<UartToolForm::Field> fields={{L"Group",uart_wide(c.group)},{L"Name",uart_wide(c.name)},{L"Format",c.hex?L"HEX":L"TEXT",{L"TEXT",L"HEX"}},{L"Payload",uart_wide(c.body),{},3},{L"Line ending",endings[static_cast<size_t>(c.ending)],endings},{L"Checksum",checksums[static_cast<size_t>(c.checksum)],checksums},{L"Checksum byte order",c.checksum_big?L"Big":L"Little",{L"Little",L"Big"}},{L"Parameter minimum",number(c.minimum)},{L"Parameter maximum",number(c.maximum)},{L"Parameter step",number(c.step)},{L"Parameter value",number(c.value)}};
    if(script){const auto step=create?ScriptStep{}:steps_[n];fields.push_back({L"Expect format",L"HEX",{L"TEXT",L"HEX"}});fields.push_back({L"Expect bytes (optional)",uart_wide(uart_hex(step.expect)),{},2});fields.push_back({L"Delay before TX (ms)",std::to_wstring(step.delay_ms)});fields.push_back({L"Expect timeout (ms)",std::to_wstring(step.timeout_ms)});fields.push_back({L"Numeric key (empty=off)",uart_wide(step.numeric_key)});fields.push_back({L"Numeric minimum",number(step.minimum)});fields.push_back({L"Numeric maximum",number(step.maximum)});}
    UartToolForm form(script?L"Script step":L"Named command",L"TEXT uses UTF-8 and {value}. HEX supports {value:u8/i8/u16le/u16be/i16le/i16be/u32le/u32be/i32le/i32be}. Checksum is appended before the ending. Preview never sends. Numeric assertion checks the first complete key:value/key=value reply after this step starts; raw Expect (if set) must also match. Reported data is not electrical/physical verification.",fields,
        [](const auto& f){PanelCommand command;std::wstring error;if(!from_fields(f,command,error))return error;std::string bytes,detail;if(!panel_payload(command,command.value,bytes,detail))return uart_wide(detail);return L"Bytes: "+std::to_wstring(bytes.size())+L"\r\n"+tx_preview(bytes,512);},
        [script](const auto& f,std::wstring& error){if(script){ScriptStep step;return step_fields(f,step,error);}PanelCommand command;return from_fields(f,command,error);},this);
    if(form.DoModal()!=IDOK||closing_)return;std::wstring error;const auto f=form.values();if(script){ScriptStep step;if(!step_fields(f,step,error)){notice(error);return;}if(create){if(steps_.size()>=128){notice(L"128 step limit.");return;}steps_.push_back(std::move(step));}else steps_[n]=std::move(step);}else{PanelCommand command;if(!from_fields(f,command,error)){notice(error);return;}auto next=commands_;if(create)next.push_back(std::move(command));else next[n]=std::move(command);std::string detail;if(!validate_panel(next,detail)){notice(uart_wide(detail));return;}commands_=std::move(next);}rebuild(create?static_cast<int>((script?steps_.size():commands_.size())-1):n);save_default();}
void UartCommandWindow::notice(const std::wstring& value){if(::IsWindow(status_))::SetWindowTextW(status_,value.c_str());}
void UartCommandWindow::state(size_t p,const std::wstring& value){const bool changed=states_[p]!=value;states_[p]=value;if(changed&&ready_&&port()==p)notice(value);}
void UartCommandWindow::transmit(){if(closing_||files_.busy()){notice(L"Wait for definition file work to finish.");return;}const auto p=port();std::wstring error;if(steps_mode()){std::string detail;if(!validate_script(steps_,detail)){notice(uart_wide(detail));return;}const auto generation=generation_(p);const auto confirm=L"Run "+std::to_wstring(steps_.size())+L" steps on Port "+(p?L"B":L"A")+L"?\r\n\r\nPayloads may execute target commands. No automatic retry/reconnect resume. Raw RX matches do not prove target success.";if(MessageBoxW(confirm.c_str(),L"Run serial script",MB_OKCANCEL|MB_ICONWARNING)!=IDOK)return;if(generation_(p)!=generation){notice(L"Connection changed during confirmation; review the port and start again.");return;}if(!start_(p,steps_,error))notice(error);return;}
    const auto n=selected();if(n<0){notice(L"Select or create a command first.");return;}auto command=commands_[n];if(!uart_number(text(value_),command.minimum,command.maximum,command.value)){notice(L"Value is outside the command range.");return;}std::string bytes,detail;if(!panel_payload(command,command.value,bytes,detail)){notice(uart_wide(detail));return;}if(!send_(p,std::move(bytes),error)){notice(error);return;}commands_[n].value=command.value;save_default();notice(L"Queued for Port "+std::wstring(p?L"B":L"A")+L"; wait for driver completion. Not a target ACK.");}
void UartCommandWindow::save_default(int kind){file(false,true,kind);}
void UartCommandWindow::file(bool importing,bool defaults,int kind){if(files_.busy()||closing_)return;const bool script=kind>=0?kind!=0:steps_mode();std::filesystem::path path=std::filesystem::path(ini_).parent_path()/(script?L"commands.sccsteps":L"commands.scccommands");bool replace=defaults;
    if(!defaults){CFileDialog dialog(importing,script?L"sccsteps":L"scccommands",path.filename().c_str(),OFN_HIDEREADONLY|(importing?OFN_FILEMUSTEXIST:OFN_OVERWRITEPROMPT),script?L"Step definitions (*.sccsteps)|*.sccsteps||":L"Command definitions (*.scccommands)|*.scccommands||",this);if(dialog.DoModal()!=IDOK)return;path=dialog.GetPathName().GetString();replace=!importing&&std::filesystem::exists(path);}
    if(importing&&defaults&&!std::filesystem::exists(path)){if(default_second_&&!script){default_second_=false;file(true,true,1);}return;}
    std::string encoded;if(!importing){try{encoded=script?encode_script(steps_):encode_panel(commands_);}catch(const std::exception& e){notice(uart_wide(e.what()));return;}}
    loading_=defaults&&importing;files_.start([path,script,importing,replace,encoded=std::move(encoded)](const std::atomic<bool>& cancel){FileResult result;result.script=script;result.loaded=importing;if(importing){const auto data=uart_read_file(path,128*1024,cancel);std::string error;const bool ok=script?decode_script(data,result.steps,error):decode_panel(data,result.commands,error);if(!ok)throw std::runtime_error(error);}else uart_write_file(path,encoded,replace,cancel);return result;});notice(importing?L"Reading and validating definitions in background...":L"Saving private definitions in background...");}
void UartCommandWindow::poll(){FileResult result;std::wstring error;if(!files_.take(result,error))return;const bool was_default=loading_;loading_=false;if(!error.empty())notice(error);else if(result.loaded){if(result.script)steps_=std::move(result.steps);else commands_=std::move(result.commands);rebuild();notice(L"Definitions loaded; nothing transmitted.");if(!was_default)save_default(result.script?1:0);}else notice(L"Definitions saved.");if(default_second_&&was_default){default_second_=false;file(true,true,1);}}
BOOL UartCommandWindow::OnCommand(WPARAM w,LPARAM l){const int action=LOWORD(w);if(action==Value&&HIWORD(w)==EN_CHANGE&&selected()>=0&&!steps_mode()){const auto& c=commands_[selected()];double value=0;if(uart_number(text(value_),c.minimum,c.maximum,value))::SendMessageW(slider_,TBM_SETPOS,TRUE,c.maximum==c.minimum?0:static_cast<int>((value-c.minimum)/(c.maximum-c.minimum)*1000));return TRUE;}if(action==Mode&&HIWORD(w)==CBN_SELCHANGE){rebuild();notice(states_[port()]);return TRUE;}if(action==Port&&HIWORD(w)==CBN_SELCHANGE){notice(states_[port()]);return TRUE;}if(action==Group&&HIWORD(w)==CBN_SELCHANGE){rebuild();return TRUE;}if(action==List&&HIWORD(w)==LBN_SELCHANGE){selection();return TRUE;}if(HIWORD(w)!=BN_CLICKED)return CDialog::OnCommand(w,l);const auto n=selected();
    if(action==New||action==Edit){edit(action==New);return TRUE;}if(action==Import||action==Export){file(action==Import);return TRUE;}if(action==SendNow){transmit();return TRUE;}if(action==Stop){stop_(port());return TRUE;}
    if(action==SaveResults){SYSTEMTIME now{};GetLocalTime(&now);auto name=capture_filename(now);name.insert(name.size()-4,port()?L"_results_B":L"_results_A");name.replace(name.size()-4,4,L".csv");CFileDialog dialog(FALSE,L"csv",name.c_str(),OFN_OVERWRITEPROMPT|OFN_HIDEREADONLY,L"CSV (*.csv)|*.csv|Log (*.log)|*.log||",this);if(dialog.DoModal()==IDOK&&!files_.busy()){const auto path=std::filesystem::path(dialog.GetPathName().GetString());const auto report=report_?report_(port()):std::string{};auto extension=path.extension().wstring();std::transform(extension.begin(),extension.end(),extension.begin(),[](wchar_t c){return static_cast<wchar_t>(towlower(c));});const auto data=extension==L".csv"?report:message_utf8(std::wstring(port()?L"Port B\r\n":L"Port A\r\n")+states_[port()]);files_.start([path,data](const std::atomic<bool>& cancel){uart_write_file(path,data,std::filesystem::exists(path),cancel);return FileResult{};});}return TRUE;}
    if(n<0)return CDialog::OnCommand(w,l);
    if(action==Minus||action==Plus){const auto& c=steps_mode()?steps_[n].command:commands_[n];double v=0;if(uart_number(text(value_),c.minimum,c.maximum,v))::SetWindowTextW(value_,number(std::clamp(v+(action==Plus?c.step:-c.step),c.minimum,c.maximum)).c_str());return TRUE;}
    if(files_.busy())return TRUE;if(action==Remove){if(steps_mode())steps_.erase(steps_.begin()+n);else commands_.erase(commands_.begin()+n);rebuild();save_default();return TRUE;}
    if((action==Up||action==Down)&&steps_mode()){const int other=n+(action==Up?-1:1);if(other>=0&&other<static_cast<int>(steps_.size())){std::swap(steps_[n],steps_[other]);rebuild(other);save_default();}return TRUE;}return CDialog::OnCommand(w,l);}
void UartCommandWindow::OnHScroll(UINT,UINT,CScrollBar* scroll){if(scroll&&scroll->GetSafeHwnd()==slider_&&selected()>=0&&!steps_mode()){const auto& c=commands_[selected()];const double ratio=::SendMessageW(slider_,TBM_GETPOS,0,0)/1000.0;const auto value=std::clamp(c.minimum+std::round((c.maximum-c.minimum)*ratio/c.step)*c.step,c.minimum,c.maximum);::SetWindowTextW(value_,number(value).c_str());}}
void UartCommandWindow::layout(){if(!ready_)return;CRect r;GetClientRect(&r);HDC dc=::GetDC(m_hWnd);const auto old=SelectObject(dc,font_);TEXTMETRICW tm{};GetTextMetricsW(dc,&tm);SelectObject(dc,old);::ReleaseDC(m_hWnd,dc);const int row=std::max<int>(28,tm.tmHeight+12),gap=8;
    ::MoveWindow(mode_,10,10,170,row*7,TRUE);::MoveWindow(port_,188,10,105,row*7,TRUE);::MoveWindow(group_,301,10,r.Width()-311,row*8,TRUE);::MoveWindow(hint_,10,row+18,r.Width()-20,row*2,TRUE);const int top=row*3+26,bottom=r.Height()-row*7-40;
    ::MoveWindow(list_,10,top,r.Width()-20,std::max(row*3,bottom-top),TRUE);int y=std::max(bottom,top+row*3)+gap;::MoveWindow(value_,10,y,160,row,TRUE);::MoveWindow(buttons_[0],178,y,40,row,TRUE);::MoveWindow(buttons_[1],226,y,40,row,TRUE);::MoveWindow(slider_,274,y,r.Width()-284,row,TRUE);y+=row+gap;
    int x=10;for(size_t i=2;i<buttons_.size();++i){wchar_t label[80]{};::GetWindowTextW(buttons_[i],label,80);HDC measure=::GetDC(m_hWnd);const auto f=SelectObject(measure,font_);SIZE size{};GetTextExtentPoint32W(measure,label,static_cast<int>(wcslen(label)),&size);SelectObject(measure,f);::ReleaseDC(m_hWnd,measure);const int width=std::max<int>(65,size.cx+24);if(x+width>r.right-10){x=10;y+=row+gap;}::MoveWindow(buttons_[i],x,y,width,row,TRUE);x+=width+gap;}y+=row+gap;::MoveWindow(status_,10,y,r.Width()-20,std::max(row,r.Height()-y-10),TRUE);}
void UartCommandWindow::OnSize(UINT type,int w,int h){CDialog::OnSize(type,w,h);if(type!=SIZE_MINIMIZED)layout();}
void UartCommandWindow::OnGetMinMaxInfo(MINMAXINFO* i){CDialog::OnGetMinMaxInfo(i);i->ptMinTrackSize.x=860;i->ptMinTrackSize.y=700;}
LRESULT UartCommandWindow::OnDpiChanged(WPARAM,LPARAM l){const auto next=make_ui_font(m_hWnd);if(next){const auto old=font_;font_=next;::EnumChildWindows(m_hWnd,[](HWND h,LPARAM f)->BOOL{::SendMessageW(h,WM_SETFONT,static_cast<WPARAM>(f),FALSE);return TRUE;},reinterpret_cast<LPARAM>(font_));if(old)DeleteObject(old);}if(l){const auto r=reinterpret_cast<const RECT*>(l);SetWindowPos(nullptr,r->left,r->top,r->right-r->left,r->bottom-r->top,SWP_NOZORDER|SWP_NOACTIVATE);}layout();return 0;}
void UartCommandWindow::OnCancel(){if(stop_){stop_(0);stop_(1);}ShowWindow(SW_HIDE);}
void UartCommandWindow::shutdown(){closing_=true;files_.cancel();if(stop_){stop_(0);stop_(1);}}
void UartCommandWindow::OnDestroy(){ready_=false;for(auto h=::GetWindow(m_hWnd,GW_CHILD);h;){const auto next=::GetWindow(h,GW_HWNDNEXT);::DestroyWindow(h);h=next;}CDialog::OnDestroy();if(font_){DeleteObject(font_);font_=nullptr;}}
